'use strict';
const E=window.SadhanaEngine;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=window.createSadhanaSession(), prepared=E.prepare(data), axis='reporting', view='overview', display='matrix', summaries=[], activeStudent=null, targets={};
let noticeDismissed=false;
let rangePreset=28;
const titles={reporting:'Reporting',rounds:'Chanting',reading:'Reading',hearing:'Hearing',wake:'Waking',sleep:'Sleeping',score:'Score'};
const fmtDate=d=>d?new Date(d+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'No submissions';
const percent=v=>Math.round(v*100)+'%';
const mean=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const clock=v=>v===null?'Unknown':String(Math.floor(v/60)).padStart(2,'0')+':'+String(Math.floor(v%60)).padStart(2,'0');
const quantity=(v,a)=>v===null?'Unknown':['wake','sleep'].includes(a)?clock(v):a==='rounds'?Math.round(v)+' rounds':a==='score'?Math.round(v)+'/100':Math.round(v*10)/10+' min';
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,7000);}
function applyDatePreset(days){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const today=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');$('endDate').value=E.shift(today,-1);$('startDate').value=E.shift($('endDate').value,1-days);rangePreset=days;}
function value(r,a=axis){return a==='score'?r.scores.total:r[a];}
function color(r,t,a=axis){if(!r)return 'missing';if(a==='reporting')return 'good';const v=value(r,a);if(v===null)return 'unknown';if(a==='score')return v>=80?'good':v>=50?'partial':'poor';if(a==='wake')return v<=300?'good':v<=420?'partial':'poor';if(a==='sleep')return v>=720&&v<1320?'good':v>=1320&&v<1440?'partial':'poor';return v>=t[a]?'good':v>0?'partial':'poor';}
function initials(name){return name.split(/\s+/).slice(0,2).map(x=>x[0]).join('');}
function nameCell(s){return '<button class="name-button" data-person="'+esc(s.id)+'"><span class="avatar">'+esc(initials(s.name))+'</span>'+esc(s.name)+'</button>';}
function status(s){
  const records=prepared.records.filter(r=>r.id===s.id);
  if(s.observed===0){const detail=!records.length?'No submissions in loaded data':records.some(r=>r.usable)?'Reports exist outside this period':'Submitted entries need date checks';return '<span class="badge warn">No reports in this period</span><div class="subtext">'+detail+'</div>';}
  if(s.gap>=7)return '<span class="badge warn">'+s.gap+' missing days at period end</span>';
  return '<span class="badge">'+percent(s.coverage)+' reported</span>';
}
function concernMinimum(){const n=+$('concernDays')?.value;return Number.isInteger(n)&&n>=1&&n<=366?n:3;}
function qualifyingStreaks(s){return s.streaks.filter(r=>r.length>=concernMinimum()&&($('concernScope')?.value!=='ongoing'||r.ongoing));}
function concernNote(s){if(view!=='concerns')return '';return qualifyingStreaks(s).map(r=>'<div class="concern-note">'+r.length+' consecutive concern days · '+r.start+' – '+r.end+' · '+r.missing+' missing, '+r.below+' below target · '+(r.ongoing?'ongoing at period end':'earlier in period')+'</div>').join('');}
function concernDay(s,i){return view==='concerns'&&qualifyingStreaks(s).some(r=>s.calendar[i]>=r.start&&s.calendar[i]<=r.end);}
function filtered(){const query=$('search').value.trim().toLowerCase(),filter=$('filter').value;
  let rows=summaries.filter(s=>view!=='concerns'||qualifyingStreaks(s).length).filter(s=>s.name.toLowerCase().includes(query)).filter(s=>filter==='all'||filter==='steady'&&s.coverage>=.8||filter==='middle'&&s.coverage>=.3&&s.coverage<.8||filter==='low'&&s.coverage<.3||filter==='gap'&&s.gap>=7||filter==='never'&&!prepared.records.some(r=>r.id===s.id)||filter==='practice'&&axis!=='reporting'&&s.rate!==null&&s.rate<.5||filter==='quality'&&s.flags.length);
  const sort=$('sort').value;rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='meets'?(a.rate??-1)-(b.rate??-1)||a.coverage-b.coverage:sort==='trend'?(a.trend??Infinity)-(b.trend??Infinity):(a.coverage-b.coverage)||a.name.localeCompare(b.name));return rows;}
function render(){
  const help=view==='help';
  if($('concernControls')){$('concernControls').hidden=view!=='concerns'||!data.rows.length;$('concernExplanation').textContent=axis==='reporting'?'Counts consecutive dates without a usable report.':'Counts below-target days and missing reports together. Unreadable values break the streak. Score target: 80; waking: by 05:00; sleeping: noon to before 22:00.';}
  if($('exportSummary'))$('exportSummary').hidden=!prepared.names.size;
  $('helpPage').hidden=!help;$('cards').hidden=help;document.querySelector('.panel').hidden=help;document.querySelector('.date-controls').hidden=help;document.querySelector('.page footer').hidden=help;$('notice').hidden=help||noticeDismissed;
  document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});
  $('qualityBadge').textContent=prepared.flags.length;
  $('datasetSummary').textContent=data.source+' · '+data.rows.length.toLocaleString()+' submissions · latest '+fmtDate(prepared.latest);
  $('sourceLabel').textContent=data.rows.length?'Imported file':'No file loaded';
  $('importSetup').hidden=help||data.rows.length>0;
  $('studentListStatus').textContent=data.roster.length?data.roster.length+' names in the student list.':'No student list added.';
  $('setupMessage').textContent='Import your Google Form response export (Excel or CSV) to get started.';
  if(help){$('crumb').textContent='Help & getting started';$('pageTitle').textContent='Getting started with Sadhana.';$('pageSubtitle').textContent='The essentials first. A few extra details below if you need them.';$('explore').hidden=true;return;}
  if(!data.rows.length){$('cards').hidden=true;document.querySelector('.panel').hidden=true;document.querySelector('.date-controls').hidden=true;$('explore').hidden=true;return;}
  const start=$('startDate').value,end=$('endDate').value;
  const error=!E.date(start)||!E.date(end)?'Choose a valid start and end date.':start>end?'Start date must be on or before end date.':'';
  $('rangeError').textContent=error;$('rangeError').hidden=!error;
  document.querySelectorAll('[data-range-days]').forEach(b=>{const selected=+b.dataset.rangeDays===rangePreset;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});
  if(error){$('rangeLabel').textContent='Custom range';$('cards').hidden=true;document.querySelector('.panel').hidden=true;$('explore').hidden=true;return;}
  const length=E.distance(end,start)+1;
  $('rangeLabel').textContent=(rangePreset===null?'Custom · ':'')+length+' '+(length===1?'day':'days');
  summaries=E.summarize(prepared,end,length,targets,axis);
  const steady=summaries.filter(s=>s.coverage>=.8).length,gaps=summaries.filter(s=>s.gap>=7).length,never=summaries.filter(s=>!prepared.records.some(r=>r.id===s.id)).length,coverage=mean(summaries.map(s=>s.coverage));
  $('cards').innerHTML=[['Listed students',summaries.length,data.roster.length?'From responses and your student list':'From imported responses','all','◌',false],['Reporting consistently',steady,'Reports for ≥80% of selected practice dates','steady','✓',false],['A gap worth noticing',gaps,'No usable report for ≥7 practice dates','gap','◷',true],['No submissions',never,'Listed, but absent from this response export','never','◇',true]].map(([label,n,note,filter,icon,warn])=>'<button class="card '+(warn?'warning':'')+'" data-filter="'+filter+'"><span class="label">'+label+'</span><span class="card-icon">'+icon+'</span><div class="number">'+n+'</div><span class="note">'+note+'</span></button>').join('');
  document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('[data-axis]').forEach(b=>b.classList.toggle('selected',b.dataset.axis===axis));
  $('crumb').textContent=view==='concerns'?'Consecutive concerns':view==='quality'?'Data quality':view==='reporting'?'Reporting & gaps':'Practice overview';
  $('pageTitle').textContent=view==='concerns'?'Consecutive days needing attention.':view==='quality'?'Make the data trustworthy.':view==='reporting'?'Showing up, and checking in.':'Every day tells a story.';
  $('pageSubtitle').textContent=view==='concerns'?'Choose a practice and the minimum streak length. Missing reports and below-target days are counted together.':view==='quality'?'See entries that need clarification before drawing conclusions.':view==='reporting'?'Missing updates are visible, even when practice is unknown.':'Explore the practices, participation, and patterns in your community.';
  document.querySelector('[data-help-topic]').dataset.helpTopic=view==='quality'?'guide-quality':'guide-calendar';
  $('explore').hidden=view==='quality';$('matrixButton').parentElement.hidden=view==='quality';$('filter').hidden=view==='quality';$('sort').hidden=view==='quality';
  if(view==='quality'){renderQuality();return;}
  const rows=filtered();$('peopleCount').textContent=rows.length+' students';
  $('panelTitle').textContent=axis==='reporting'?'Consistency, at a glance':titles[axis]+', day by day';
  $('panelSubtitle').textContent='Practice dates: '+fmtDate(start)+' – '+fmtDate(end)+'. Click a name to explore their history.';
  $('legend').innerHTML=(axis==='reporting'?[['good','Report received'],['missing','No usable report']]:[['good',axis==='score'?'Score ≥80':'Target met'],['partial',axis==='score'?'Score 50–79':'Some practice / later schedule'],['poor',axis==='score'?'Score <50':'Zero practice / outside schedule'],['unknown','Value needs clarification'],['missing','No usable report']]).map(([c,t])=>'<span><i class="dot '+c+'"></i>'+t+'</span>').join('');
  $('content').innerHTML=rows.length?(display==='matrix'?matrix(rows):table(rows)):'<div class="empty">No students match these filters.</div>';
  $('panelFoot').textContent='Reporting coverage: '+percent(coverage||0)+' across listed names. Practice averages use known reported days; missing reports do not become zero practice. '+(axis==='reporting'?'Latest valid submission per person/date is retained.':axis==='score'?'Scores are recalculated using the PDF and confirmed or default targets.':'Targets: 16 rounds / 60 min reading / 60 min hearing until confirmed; waking by 05:00, sleeping before 22:00.');
}
function matrix(rows){const dates=rows[0].calendar;return '<table class="matrix"><thead><tr><th class="person">STUDENT</th>'+dates.map(d=>{const x=new Date(d+'T00:00:00Z');return '<th class="day" title="'+d+'">'+x.getUTCDate()+'<span>'+x.toLocaleDateString('en-GB',{weekday:'narrow',timeZone:'UTC'})+'</span></th>';}).join('')+'<th>REPORTED</th><th>'+(axis==='reporting'?'STATUS':'TARGET MET')+'</th></tr></thead><tbody>'+rows.map(s=>'<tr><td class="person">'+nameCell(s)+concernNote(s)+'</td>'+s.history.map((r,i)=>'<td class="day"><button class="square '+color(r,s.target)+(concernDay(s,i)?' concern-day':'')+'" data-person="'+esc(s.id)+'" aria-label="'+esc(s.name+' '+dates[i]+' '+(r?axis==='reporting'?'Reported':quantity(value(r),axis):'No usable report'))+'" title="'+esc(dates[i]+': '+(r?axis==='reporting'?'Reported; submitted '+r.submitted.date:quantity(value(r),axis):'No usable report'))+'"></button></td>').join('')+'<td class="metric">'+s.observed+'/'+dates.length+'<div class="coverage-track"><i style="width:'+percent(s.coverage)+'"></i></div></td><td class="metric">'+(axis==='reporting'?status(s):s.known?s.meets+'/'+s.known+' known days':'Unknown')+'</td></tr>').join('')+'</tbody></table>';}
function table(rows){return '<table><thead><tr><th>STUDENT</th><th>REPORTING</th><th>LAST SUBMITTED*</th><th>AVERAGE</th><th>TARGET MET</th><th>CHANGE*</th><th>STATUS</th></tr></thead><tbody>'+rows.map(s=>'<tr><td>'+nameCell(s)+concernNote(s)+'</td><td>'+s.observed+'/'+s.calendar.length+' <span class="subtext">'+percent(s.coverage)+'</span></td><td>'+fmtDate(s.last)+'</td><td>'+(axis==='reporting'?'—':quantity(s.average,axis))+'</td><td>'+(axis==='reporting'?'—':s.known?s.meets+'/'+s.known:'Unknown')+'</td><td>'+(axis==='reporting'||s.trend===null?'—':(s.trend>0?'+':'')+Math.round(s.trend*10)/10+(['wake','sleep','reading','hearing'].includes(axis)?' min':axis==='score'?' points':' rounds'))+'</td><td>'+status(s)+'</td></tr>').join('')+'</tbody></table><div class="quality-intro">* Last submission on or before period end. Change compares reported values in the second half with the first half; it needs at least three known days in each half.</div>';}
function renderQuality(){const query=$('search').value.trim().toLowerCase();const rows=prepared.flags.filter(f=>(f.name+' '+f.type+' '+f.message).toLowerCase().includes(query));$('panelTitle').textContent='Entries to clarify';$('panelSubtitle').textContent='All dates in the loaded export. Future-dated and invalid-date entries are excluded from practice history.';$('peopleCount').textContent=rows.length+' flags';$('legend').innerHTML='<span><i class="dot poor"></i>Future dates</span><span><i class="dot unknown"></i>Invalid / unclear values</span><span><i class="dot partial"></i>Duplicate days</span>';$('content').innerHTML=rows.length?'<table><thead><tr><th>STUDENT</th><th>ISSUE</th><th>SOURCE ROW</th><th>DETAIL</th></tr></thead><tbody>'+rows.map(f=>'<tr><td>'+nameCell(f)+'</td><td><span class="badge '+(f.type==='Future date'?'red':'warn')+'">'+esc(f.type)+'</span></td><td>'+f.row+'</td><td class="issue-message">'+esc(f.message)+'</td></tr>').join('')+'</tbody></table>':'<div class="empty">No data-quality flags match your search.</div>';$('panelFoot').textContent='Flags invite clarification. Original values are retained. No dates or ambiguous inputs have been silently repaired.';}
function student(id){activeStudent=id;const s=summaries.find(s=>s.id===id);if(!s)return;$('studentName').textContent=s.name;const records=prepared.records.filter(r=>r.id===id);const last=records.filter(r=>r.submitted).map(r=>r.submitted.date).sort().pop();const candidates=(data.prescriptions||[]).filter(p=>E.key(p.name)===id);const t=s.target;
  const hist=s.history.map((r,i)=>r?{...r,d:s.calendar[i]}:{d:s.calendar[i]});const values=hist.map(r=>r.scores?.total);const points=values.map((v,i)=>v==null?'':(15+i*970/Math.max(1,values.length-1))+','+(90-v*.7));
  const segments=[];let seg=[];points.forEach(p=>{if(p)seg.push(p);else if(seg.length){segments.push(seg);seg=[];}});if(seg.length)segments.push(seg);
  $('studentContent').innerHTML='<div class="student-body"><div class="student-stats"><div class="student-stat">Reporting in this period<strong>'+s.observed+'/'+s.calendar.length+'</strong>'+percent(s.coverage)+' of selected practice dates</div><div class="student-stat">Last submitted in loaded data<strong style="font-size:21px">'+fmtDate(last)+'</strong>'+records.length+' submissions in this export</div><div class="student-stat">Entries to clarify<strong>'+s.flags.length+'</strong>'+s.gap+' trailing practice dates without a report</div></div><h3>Daily score history</h3><p>Raw observations recalculated from the PDF. Gaps stay empty; totals require five readable components.</p><svg class="sparkline" viewBox="0 0 1000 100" preserveAspectRatio="none" role="img" aria-label="Daily score chart with gaps for missing or unreadable reports"><line x1="15" y1="20" x2="985" y2="20" stroke="#e2e8de"/><line x1="15" y1="90" x2="985" y2="90" stroke="#e2e8de"/>'+segments.map(p=>'<polyline points="'+p.join(' ')+'" fill="none" stroke="#588467" stroke-width="2"/>').join('')+points.filter(Boolean).map(p=>{const [x,y]=p.split(',');return '<circle cx="'+x+'" cy="'+y+'" r="3" fill="#588467"/>';}).join('')+'</svg><h3>Personal targets</h3><p>'+ (targets[id]?'Confirmed for this tab.':'Using the PDF defaults. Confirm the mentor’s personal targets here.')+'</p><form class="target-form" id="targetForm"><label>Rounds<input name="rounds" type="number" min="1" step="1" max="1000" required value="'+t.rounds+'"></label><label>Reading (min)<input name="reading" type="number" min="1" max="1440" required value="'+t.reading+'"></label><label>Hearing (min)<input name="hearing" type="number" min="1" max="1440" required value="'+t.hearing+'"></label><button type="submit">Confirm targets</button><button type="button" id="defaultTargets">Use defaults</button></form>'+ (candidates.length?'<p>Workbook target entries to verify: '+candidates.map(p=>esc(p.name.trim())+' — '+p.rounds+' rounds, '+p.reading+' min reading, '+p.hearing+' min hearing').join('; ')+'.</p>':'')+'<h3>Practice and reporting, side by side</h3><div class="history-scroll"><table><thead><tr><th>PRACTICE DATE</th><th>SUBMITTED</th><th>DELAY</th><th>ROUNDS</th><th>READING</th><th>HEARING</th><th>SLEEP</th><th>WAKE</th><th>SCORE</th></tr></thead><tbody>'+hist.slice().reverse().map(r=>'<tr><td>'+r.d+'</td>'+(r.scores?'<td>'+r.submitted.date+'</td><td class="delay">'+E.distance(r.submitted.date,r.d)+' d</td><td>'+quantity(r.rounds,'rounds')+'</td><td>'+quantity(r.reading,'reading')+'</td><td>'+quantity(r.hearing,'hearing')+'</td><td>'+clock(r.sleep)+'</td><td>'+clock(r.wake)+'</td><td>'+quantity(r.scores.total,'score')+'</td>':'<td colspan="8"><span class="badge warn">No usable report — practice unknown</span></td>')+'</tr>').join('')+'</tbody></table></div>'+ (s.flags.length?'<h3>Data-quality notes · all export dates</h3><ul>'+s.flags.slice(0,30).map(f=>'<li>'+esc(f.type)+': '+esc(f.message)+' (row '+f.row+')</li>').join('')+'</ul>'+(s.flags.length>30?'<p>Showing the first 30. All flags are in Data quality.</p>':''):'')+'</div>';
  $('targetForm').onsubmit=event=>{event.preventDefault();const form=new FormData(event.target);targets[id]={rounds:+form.get('rounds'),reading:+form.get('reading'),hearing:+form.get('hearing')};render();student(id);toast('Personal targets confirmed. History has been recalculated.');};$('defaultTargets').onclick=()=>{delete targets[id];render();student(id);};if(!$('studentDialog').open)$('studentDialog').showModal();
}
function importedRows(workbook){
  for(const name of workbook.SheetNames){const rows=XLSX.utils.sheet_to_json(workbook.Sheets[name],{header:1,raw:true,defval:null});let headerIndex=rows.findIndex(r=>r.some(v=>/timestamp/i.test(String(v)))&&r.some(v=>/name|नाम/i.test(String(v))));if(headerIndex<0)continue;
    const h=rows[headerIndex].map(x=>String(x||'').trim().toLowerCase());const col={timestamp:h.findIndex(x=>x.includes('timestamp')),date:h.findIndex(x=>x.startsWith('date')||x.includes('तिथि')),name:h.findIndex(x=>x.includes('name')||x.includes('नाम')),rounds:h.findIndex(x=>x.includes('chanted')||x.includes('आज के जप')),reading:h.findIndex(x=>x.includes('total reading')||x.includes('कुल अध्ययन')),hearing:h.findIndex(x=>x.includes('total hearing')||x.includes('कुल सुनने')),sleep:h.findIndex(x=>x.includes('sleeping')||x.includes('सोने का समय')),wake:h.findIndex(x=>x.includes('wake-up')||x.includes('जागने का समय'))};
    if(Object.values(col).some(x=>x<0))continue;
    const excelDate=v=>{if(typeof v!=='number')return v;const d=XLSX.SSF.parse_date_code(v);return d?String(d.y).padStart(4,'0')+'-'+String(d.m).padStart(2,'0')+'-'+String(d.d).padStart(2,'0')+'T'+String(d.H).padStart(2,'0')+':'+String(d.M).padStart(2,'0')+':'+String(Math.floor(d.S)).padStart(2,'0'):String(v);};
    const output=[];for(let n=headerIndex+1;n<rows.length;n++){const row=rows[n];if(row[col.timestamp]===null||row[col.timestamp]==='')continue;const r={row:n+1};for(const [field,c] of Object.entries(col)){let v=row[c];if(['timestamp','date'].includes(field))v=excelDate(v);if(['reading','hearing'].includes(field)&&typeof v==='number')v={kind:'minutes',value:v*1440};if(['wake','sleep'].includes(field)&&typeof v==='number'&&v>=0&&v<1)v={kind:'clock',value:v*1440};r[field]=v;}output.push(r);}return output;
  }throw new Error('Could not find the eight Google Form response columns. Import the raw response export with its header row.');
}
function importedRoster(workbook){
  for(const sheet of workbook.SheetNames){
    const rows=XLSX.utils.sheet_to_json(workbook.Sheets[sheet],{header:1,raw:false,defval:''});
    const header=rows.findIndex(r=>r.some(v=>/^(name|full name|student name|नाम|name\s*\/\s*नाम)$/i.test(String(v).trim())));
    if(header<0)continue;
    const col=rows[header].findIndex(v=>/^(name|full name|student name|नाम|name\s*\/\s*नाम)$/i.test(String(v).trim()));
    const names=new Map();for(const row of rows.slice(header+1)){const name=String(row[col]||'').trim();if(name)names.set(E.key(name),name);}
    if(names.size)return Array.from(names.values());
  }
  throw new Error('Use a student list with a Name column and one student name per row.');
}
$('rosterUpload').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw new Error('Please use a student list smaller than 30 MB.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const roster=importedRoster(wb);data={...data,roster,rosterSource:file.name};prepared=E.prepare(data);render();toast('Loaded '+roster.length+' student names. Names in responses are also retained.');}catch(error){toast(error.message||'This student list could not be imported.');}event.target.value='';};
$('upload').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw new Error('Please use an export smaller than 30 MB.');const buffer=await file.arrayBuffer();const wb=XLSX.read(buffer,{type:'array',cellDates:false,raw:/\.csv$/i.test(file.name)});const rows=importedRows(wb);if(!rows.length)throw new Error('No timestamped responses were found.');data={...data,source:file.name,rows,prescriptions:[]};prepared=E.prepare(data);render();toast('Imported '+rows.length.toLocaleString()+' responses. Scores recalculated from raw fields.');}catch(error){toast(error.message||'This file could not be imported.');}event.target.value='';};
document.addEventListener('click',event=>{const person=event.target.closest('[data-person]');if(person){student(person.dataset.person);return;}const nav=event.target.closest('[data-view]');if(nav){view=nav.dataset.view;if(view==='reporting')axis='reporting';render();if(view==='help')window.scrollTo({top:0,behavior:'smooth'});return;}const a=event.target.closest('[data-axis]');if(a){axis=a.dataset.axis;render();return;}const card=event.target.closest('[data-filter]');if(card){view='reporting';axis='reporting';$('filter').value=card.dataset.filter;render();$('content').scrollIntoView({behavior:'smooth',block:'nearest'});return;}const close=event.target.closest('[data-close]');if(close)$(close.dataset.close).close();});
document.addEventListener('click',event=>{
  const topic=event.target.closest('[data-help-topic]');if(topic){view='help';render();const section=$(topic.dataset.helpTopic);if(section.tagName==='DETAILS')section.open=true;section.scrollIntoView({behavior:'smooth',block:'start'});return;}
  const route=event.target.closest('[data-guide-view]');if(route){view=route.dataset.guideView;axis=route.dataset.guideAxis||'reporting';$('filter').value=route.dataset.guideFilter||'all';$('search').value='';render();window.scrollTo({top:0,behavior:'smooth'});return;}
  if(event.target.closest('[data-guide-method]'))$('methodDialog').showModal();
});
for(const id of ['startDate','endDate'])$(id).addEventListener('change',()=>{rangePreset=null;render();});
for(const id of ['filter','sort'])$(id).addEventListener('change',render);$('search').addEventListener('input',render);
document.querySelectorAll('[data-range-days]').forEach(b=>b.addEventListener('click',()=>{applyDatePreset(+b.dataset.rangeDays);render();}));
$('matrixButton').onclick=()=>{display='matrix';$('matrixButton').classList.add('selected');$('tableButton').classList.remove('selected');render();};$('tableButton').onclick=()=>{display='table';$('tableButton').classList.add('selected');$('matrixButton').classList.remove('selected');render();};
$('settingsButton').onclick=()=>$('settingsDialog').showModal();
$('methodButton').onclick=()=>$('methodDialog').showModal();$('dismissNotice').onclick=()=>{noticeDismissed=true;$('notice').hidden=true;};
$('resetData').onclick=()=>{data=window.createSadhanaSession();targets={};prepared=E.prepare(data);view='overview';$('search').value='';$('filter').value='all';if($('studentDialog').open)$('studentDialog').close();render();toast('Responses, student list and targets cleared from this tab.');};
// Require both ends of the gesture on the backdrop, so dragging out of a dialog does not dismiss it.
$('importResponses').onclick=()=>$('upload').click();
$('importStudentList').onclick=()=>$('rosterUpload').click();
let backdropPress=null;
const outsideDialog=(event,dialog)=>{const r=dialog.getBoundingClientRect();return event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom;};
document.addEventListener('pointerdown',event=>{const dialog=event.target.closest('dialog[open]');backdropPress=dialog&&event.target===dialog&&outsideDialog(event,dialog)?{dialog,pointer:event.pointerId}:null;});
document.addEventListener('pointerup',event=>{const press=backdropPress;backdropPress=null;if(press&&press.pointer===event.pointerId&&press.dialog.open&&event.target===press.dialog&&outsideDialog(event,press.dialog))press.dialog.close();});
document.addEventListener('pointercancel',()=>{backdropPress=null;});
applyDatePreset(28);render();
